head.script:
// DOM 조회 순서(받은 id → mf_ 접두사 → G_ 뒤 접두사 → 접두사 제거). 2026-11
scwin.__getDom = function(id) {
	var P = 'mf_', d = function(k) { return document.getElementById(k); }, dd = function(k) { return k.replace(/(mf_){2,}/g, P); };
	var r = d(id); if (r) return r;
	var s = dd(P + id); r = d(s); if (r) return r;
	var g = s.indexOf('G_');
	if (g >= 0) { s = dd(s.slice(0, g + 2) + P + s.slice(g + 2)); r = d(s); if (r) return r; s = dd(P + s); r = d(s); if (r) return r; }
	return d(s.replace(P, ''));
};
// jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
	var j = $(q); if (j.length) return j;
	var P = 'mf_', t = q.trim(), r = t.slice(1);
	if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
	return $(t.slice(0, 1) + r);
};
scwin.onpageload = function() {
	scwin.tabIndex = 1;
};
scwin.addTab = function(label, tabId, src) {
	var tabOpt = {
		label: label,
		closable: true
	};
	var contOpt = {
		frameMode: "wframe",
		scope: true,
		src: src,
		alwaysDraw: false,
		title: tabId
	};
	tac_main.addTab(tabId, tabOpt, contOpt);
};
scwin.btn_trigger1_onclick = function(e) {
	var tabId = "tab" + scwin.tabIndex;
	var label = tabId;
	var src = "/sample/common_link/dataList_removeAll_WEFF-674_(WSQ-4016)_sub.xml";
	scwin.addTab(label, tabId, src);
	scwin.tabIndex++;
};
scwin.checkVal = function() {
	return scwin.__getJq(scwin.__getDom($p.id + 'tac_main_contents_tab1_body_gridView1_body_tbody').children[0]).hasClass('w2grid_hidedRow') == true;
};
